function respawns(dt){for(const p of allPlayers()){if(p.dead<=0)continue;p.dead=isHost?p.dead-dt:Math.max(.04,p.dead-dt);if(p.dead<=0&&isHost){resetLife(p);shotChecks[p.side]={last:-10,ammo:[30,8,5],gun:0,reloading:0};if(p===local){recoil=0;recoilPitch=0;announce('BACK IN THE FIGHT',1)}else remoteTarget=packetPlayer(p);if(remotes.has(p.side))remotes.get(p.side).target=packetPlayer(p);if(online)link.send({t:'respawn',id:matchId,side:p.side});}}}
function tick(dt){pollController(dt);totalTime+=dt;medalTime-=dt;rivalPing=Math.max(0,rivalPing-dt);if(medalTime<=0)hide('medal');toastTime-=dt;if(toastTime<=0)$('toast').style.opacity=0;shotFlash=Math.max(0,shotFlash-dt);hitFlash=Math.max(0,hitFlash-dt);hurt=Math.max(0,hurt-dt*1.5);recoil=lerp(recoil,0,1-Math.exp(-13*dt));recoilPitch=lerp(recoilPitch,0,1-Math.exp(-11*dt));swayX=lerp(swayX,0,1-Math.exp(-8*dt));swayY=lerp(swayY,0,1-Math.exp(-8*dt));
if(mode==='match'){
 if(countdown>0){announce(''+Math.max(1,Math.ceil(countdown)),.1);if(countdown<=0){matchActive=true;announce('BREACH',.7);sound('start');}}
 if((!paused||online)&&matchActive){
 const pad=activeInput==='ps5'?padFrame?.actions:null;const input={forward:paused?0:pad?pad.forward:activeInput==='kbm'?(keys.KeyW?1:0)-(keys.KeyS?1:0):0,strafe:paused?0:pad?pad.strafe:activeInput==='kbm'?(keys.KeyD?1:0)-(keys.KeyA?1:0):0,sprint:!paused&&(pad?pad.sprint:activeInput==='kbm'&&(keys.ShiftLeft||keys.ShiftRight)),aim,jump:!paused&&(pad?pad.jump:jumpPress),slide:!paused&&(pad?pad.slide:slidePress),dash:!paused&&(pad?pad.dash:dashPress)};if(!paused&&activeInput==='kbm'){local.yaw+=((keys.ArrowLeft?1:0)-(keys.ArrowRight?1:0))*dt*2;local.pitch=clamp(local.pitch+((keys.ArrowUp?1:0)-(keys.ArrowDown?1:0))*dt*1.4,-1.4,1.4)}
 const wasGrounded=local.grounded,oldPad=local.padCd;movePlayer(local,input,dt);if(local.padCd>oldPad+.5){sound('jump',2);showMedal({medal:'LIFT OFF',reward:'AERIAL ROUTE · KEEP MOVING'});}if(input.jump&&wasGrounded){sound('jump')};if(!wasGrounded&&local.grounded){recoil=.22;sound('step',3)};if(local.grounded&&Math.hypot(local.vx,local.vz)>2&&totalTime-footClock>.37){footClock=totalTime;sound('step')}
 if(!paused&&(pad?(pad.fire&&WEAPONS[local.gun].auto||pad.firePress):(mouseFire&&WEAPONS[local.gun].auto||firePress)))fire();jumpPress=false;slidePress=false;dashPress=false;firePress=false;
 if(!online)updateBot(dt);
 if(online&&totalTime-lastNet>1/30){lastNet=totalTime;if(local.dead<=0)link.state(packetPlayer(local),matchId);}
 
 }
 if(online&&!isHost)for(const r of remotes.values()){const p=r.p,t=r.target;p.x=lerp(p.x,t.x,1-Math.exp(-18*dt));p.y=lerp(p.y,t.y,1-Math.exp(-18*dt));p.z=lerp(p.z,t.z,1-Math.exp(-18*dt));p.yaw=angleLerp(p.yaw,t.yaw,1-Math.exp(-20*dt));p.pitch=lerp(p.pitch,t.pitch,1-Math.exp(-20*dt));p.gun=t.gun;p.slide=t.slide?.3:0;}
 if(local.dead>0)announce('SUIT OFFLINE\nRESPAWN IN '+Math.ceil(local.dead),.2);
 hudClock+=dt;if(hudClock>=.05){hudClock=0;updateHUD();}
}
announceTime-=dt;if(announceTime<=0)$('announcement').textContent='';feedTime-=dt;if(feedTime<=0)$('feed').style.opacity=0;
updateHillVisual();arena.update(totalTime,settings.motion==='reduced');powerVisuals.update(totalTime,powerNodes,settings.motion==='reduced');updateFX(dt);cells.forEach(c=>{c.mesh.visible=c.cool<=0;c.mesh.rotation.y=totalTime;c.mesh.position.y=c.y+.55+Math.sin(totalTime*2)*.06;});
}
function updateCells(dt){cells.forEach((cell,i)=>{cell.cool=Math.max(0,cell.cool-dt);if(!isHost||cell.cool>0)return;for(const p of allPlayers()){if(p.dead<=0&&p.hp<100&&Math.hypot(p.x-cell.x,p.z-cell.z)<1.05&&Math.abs(p.y-cell.y)<.6){p.hp=Math.min(100,p.hp+35);cell.cool=12;burst({x:cell.x,y:cell.y+.6,z:cell.z},0x8dffca,18);if(p===local){announce('+35 INTEGRITY',1);sound('start')}if(online)link.send({t:'heal',id:matchId,side:p.side,hp:p.hp,cell:i});break;}}});}
let lastRivalX=0,lastRivalZ=0,renderRival=null;
function render(dt){
 const inGame=mode==='match'||mode==='result';
 if(inGame){const speed=Math.hypot(local.vx,local.vz),bob=settings.motion!=='reduced'&&local.grounded&&local.dead<=0?Math.sin(local.walk*1.7)*Math.min(.032,speed*.005):0;
 camera.position.set(local.x,local.y+local.eye+bob,local.z);camera.rotation.set(local.pitch+recoilPitch,local.yaw,settings.motion==='reduced'?0:(local.slide>0?-.045:0)+Math.sin(local.walk*.85)*Math.min(.007,speed*.001));
 const targetFov=settings.motion!=='reduced'&&local.dash>0?settings.fov+15:aim&&local.dead<=0?WEAPONS[local.gun].ads:settings.fov+(speed>8?5:0);camera.fov=lerp(camera.fov,targetFov,1-Math.exp(-12*dt));camera.updateProjectionMatrix();
 const rivalSpeed=Math.hypot(rival.x-lastRivalX,rival.z-lastRivalZ)/Math.max(.001,dt);lastRivalX=rival.x;lastRivalZ=rival.z;if(!renderRival||Math.hypot(renderRival.x-rival.x,renderRival.z-rival.z)>6)renderRival={...rival};renderRival={...rival,x:lerp(renderRival.x,rival.x,1-Math.exp(-22*dt)),y:lerp(renderRival.y,rival.y,1-Math.exp(-22*dt)),z:lerp(renderRival.z,rival.z,1-Math.exp(-22*dt)),yaw:angleLerp(renderRival.yaw,rival.yaw,1-Math.exp(-22*dt))};rivalModel.update(renderRival,totalTime,rivalSpeed);if(online&&!remotes.has(rival.side))rivalModel.root.visible=false;rivalModel.shield.visible=rival.dead<=0&&(rival.shield>0||rival.armor>0);rivalModel.shield.material.color.setHex(rival.armor>0?0xbfa1ff:0x8bdcf4);for(const r of remotes.values()){if(r.model===rivalModel)continue;const moving=Math.hypot(r.p.x-(r.lastX??r.p.x),r.p.z-(r.lastZ??r.p.z))/Math.max(dt,.001);r.model.update(r.p,totalTime,moving);r.lastX=r.p.x;r.lastZ=r.p.z;r.model.shield.visible=r.p.dead<=0&&(r.p.armor>0||r.p.shield>0);}
 }else{const a=.34+Math.sin(totalTime*.065)*.08;camera.position.set(17*Math.sin(a)+5,5.6,16.5);camera.lookAt(-1.3,2,0);camera.fov=66;camera.updateProjectionMatrix();rivalModel.root.visible=false;for(const r of remotes.values())r.model.root.visible=false;}
 renderer.autoClear=true;if(bloom.enabled)composer.render(dt);else renderer.render(scene,camera);
 if(mode==='match'&&local.dead<=0){const w=WEAPONS[local.gun],reloadProgress=local.reload>0?1-local.reload/w.reload:0,reloadDip=local.reload>0?Math.sin(reloadProgress*Math.PI):0;view.guns.forEach((g,i)=>{g.group.visible=i===local.gun&&!(aim&&i===2);g.flash.visible=i===local.gun&&shotFlash>0&&!aim;g.flash.rotation.z=Math.random()*6;g.lamp.intensity=shotFlash>0?3:0;});const gun=view.guns[local.gun].group;const ads=aim?1:0;
 gun.position.x=lerp(gun.position.x,ads?.08:.29,1-Math.exp(-16*dt));gun.position.y=lerp(gun.position.y,ads?-.25:-.28,1-Math.exp(-16*dt));view.rig.position.set(settings.motion==='reduced'?0:Math.sin(local.walk*1.3)*.007+swayX,(settings.motion==='reduced'?0:Math.abs(Math.cos(local.walk*1.3))*.006-swayY)-reloadDip*.22,recoil*(ads?.018:.065));view.rig.rotation.set(recoil*(ads?.018:.11)-reloadDip*.35,-reloadDip*.4,-reloadDip*.6+(local.slide>0?.18:0)+swayX*2);
 renderer.autoClear=false;renderer.clearDepth();renderer.render(view.scene,view.camera);renderer.autoClear=true;}
}
let perfWindow=0,capLast=performance.now(),capBudget=0;function frame(now){capBudget+=now-capLast;capLast=now;const cap=document.hidden?15:+settings.frameLimit;if(cap&&capBudget<1000/cap){requestAnimationFrame(frame);return;}if(cap)capBudget%=1000/cap;else capBudget=0;const rawDt=Math.max(.0001,(now-last)/1000),dt=Math.min(.045,rawDt);last=now;tick(dt);render(dt);frameSum+=rawDt;perfSeconds+=rawDt;perfFrames++;if(perfSeconds>=3){const fps=perfFrames/perfSeconds;if(settings.quality==='auto'&&rawDt<.15&&!document.hidden){const next=clamp(renderScale+(fps<Math.min(+settings.frameLimit||60,60)*.8?-.12:fps>Math.min(+settings.frameLimit||60,60)*.96?.05:0),.5,Math.min(devicePixelRatio,1.5)*settings.renderPercent/100);if(Math.abs(next-renderScale)>.01){renderScale=next;renderer.setPixelRatio(next);composer.setPixelRatio(next);}}perfSeconds=0;perfFrames=0;}frameCount++;if(frameSum>=1){$('fps').textContent=Math.round(frameCount/frameSum)+' FPS';frameSum=0;frameCount=0;}requestAnimationFrame(frame);}

function pause(){if(mode!=='match'||paused)return;paused=true;clearInput();unlock();$('pause-note').textContent=online?'The match keeps running while this menu is open.':'Your practice is paused.';show('pause-screen');}
function resume(){hide('pause-screen');paused=false;lock();}
document.addEventListener('keydown',e=>{if(e.target.matches('input,select')||$('settings').open||$('guide').open)return;if(mode==='match'&&['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Tab','ControlLeft','ControlRight'].includes(e.code))e.preventDefault();if(e.code==='Escape'&&mode==='match'){e.preventDefault();paused?resume():pause();return;}if(e.code==='Tab'&&mode==='match'){keys.Tab=true;updateMatchboard();return;}if(!claimKeyboardMouse())return;keys[e.code]=true;if(e.repeat)return;if(e.code==='Escape'&&mode==='match')pause();if(e.code==='Space')jumpPress=true;if(e.code==='KeyQ')dashPress=true;if(e.code==='KeyE')useBoost();if(e.code==='KeyC'||e.code.startsWith('Control'))slidePress=true;if(e.code==='KeyR')reloadGun();if(['Digit1','Digit2','Digit3'].includes(e.code))switchGun(+e.code.slice(-1)-1);if(e.code==='KeyF'){if(!document.fullscreenElement)document.documentElement.requestFullscreen?.().catch(()=>toast('Fullscreen is unavailable in this preview.'));else document.exitFullscreen?.();}});
document.addEventListener('keyup',e=>{keys[e.code]=false;if(e.code==='Tab')updateMatchboard();});document.addEventListener('mousemove',e=>{if((!locked&&!(dragLook&&(mouseFire||aim)))||paused||mode!=='match')return;if(Math.abs(e.movementX)+Math.abs(e.movementY)>1&&!claimKeyboardMouse())return;const scale=.0017*settings.sensitivity*(aim?.65:1);local.yaw-=e.movementX*scale;local.pitch=clamp(local.pitch-e.movementY*scale,-1.42,1.42);swayX=clamp(swayX-e.movementX*.000055,-.022,.022);swayY=clamp(swayY-e.movementY*.00005,-.02,.02)});
renderer.domElement.addEventListener('mousedown',e=>{if(mode!=='match'||paused||!claimKeyboardMouse())return;if(!locked&&!dragLook){lock();return}if(e.button===0){mouseFire=true;firePress=true}if(e.button===2)aim=true});document.addEventListener('mouseup',e=>{if(e.button===0)mouseFire=false;if(e.button===2&&activeInput==='kbm')aim=false});document.addEventListener('contextmenu',e=>{if(mode==='match')e.preventDefault()});
document.addEventListener('pointerlockchange',()=>{locked=document.pointerLockElement===renderer.domElement;if(locked){pendingLock=false;if(mode==='match'){paused=false;hide('pause-screen');}}else if(mode==='match'&&!paused&&!pendingLock&&!dragLook&&activeInput==='kbm')pause();});window.addEventListener('blur',()=>{if(mode==='match')pause();});document.addEventListener('visibilitychange',()=>{if(document.hidden&&mode==='match')pause();});
renderer.domElement.addEventListener('wheel',e=>{if(mode==='match'&&!paused&&claimKeyboardMouse()){e.preventDefault();switchGun((local.gun+(e.deltaY>0?1:2))%3)}},{passive:false});
$('practice').onclick=practice;$('host').onclick=()=>openRoom(true);$('join').onclick=()=>openRoom(false);$('ready').onclick=ready;$('leave-room').onclick=lobby;$('resume').onclick=resume;$('quit').onclick=lobby;$('result-quit').onclick=lobby;$('rematch').onclick=rematch;
