function applyEnhancementSettings(){arena.setAtmosphere(settings.atmosphere);document.documentElement.style.setProperty('--reticle',{mint:'#a1ffe1',white:'#ffffff',pink:'#ff72cf',gold:'#ffe278'}[settings.reticle]);}

function setInputDevice(device){if(device===activeInput)return;activeInput=device;clearInput();if(device==='ps5')unlock();updateInputPrompts();}
function claimKeyboardMouse(){if(settings.inputMode==='ps5')return false;if(settings.inputMode==='auto')setInputDevice('kbm');return true;}
function updateInputPrompts(){const ps=activeInput==='ps5';document.body.classList.toggle('ps5-input',ps);$('input-badge').textContent=ps?'PS5 CONTROLLER':'KEYBOARD / MOUSE';$('input-help').textContent=ps?'✕ JUMP   ○ SLIDE   □ RELOAD   △ SWITCH   L2 AIM   R2 FIRE':'WASD MOVE · SPACE JUMP · R RELOAD · MOUSE AIM / FIRE';document.querySelectorAll('[data-slot] b').forEach(el=>el.textContent=ps?'△':String(+el.parentElement.dataset.slot+1));}
function setupControllerSettings(){if(!['auto','kbm','ps5'].includes(settings.inputMode))settings.inputMode='auto';settings.padSensitivity=clamp(+settings.padSensitivity||1.2,.4,3);settings.deadzone=clamp(+settings.deadzone||.14,.05,.3);$('input-mode').value=settings.inputMode;$('input-mode').onchange=()=>{settings.inputMode=$('input-mode').value;controller.reset();setInputDevice(settings.inputMode==='ps5'?'ps5':'kbm');saveSettings();updateInputPrompts();};for(const [id,key]of[['pad-sensitivity','padSensitivity'],['pad-deadzone','deadzone']]){$(id).value=settings[key];$(id).oninput=()=>{settings[key]=+$(id).value;$(id+'-value').textContent=key==='deadzone'?Math.round(settings[key]*100)+'%':settings[key].toFixed(1);saveSettings();};$(id).oninput();}updateInputPrompts();}
function pollController(dt){
 const context=mode+'|'+paused+'|'+local.life+'|'+$('settings').open+'|'+$('guide').open;if(context!==padContext){controller.reset();padContext=context;}
 padFrame=controller.poll(settings.deadzone);if(padFrame.disconnected&&activeInput==='ps5'){clearInput();pause();toast('Controller disconnected. Reconnect and resume, or choose Keyboard & Mouse in Settings.');if(settings.inputMode==='auto')setInputDevice('kbm');}
 if(document.hidden){controller.reset();padFrame.actions=null;return;}
 if(settings.inputMode==='auto'&&padFrame.activity)setInputDevice('ps5');
 padUiClock+=dt;if(padUiClock>.25){padUiClock=0;const text=controller.error||(padFrame.unsupported?'Unmapped controller. Try USB with desktop Chrome or Edge.':padFrame.connected?'Controller connected · '+(padFrame.armed?'ready':'release buttons to start'):'Connect via USB or Bluetooth, then press a controller button.');if(text!==padStatus){padStatus=text;$('controller-status').textContent=text;}}
 if(activeInput!=='ps5'||!padFrame.actions)return;const a=padFrame.actions;
 if($('settings').open||$('guide').open||mode!=='match'||paused){controllerMenu(a,dt);return;}
 if(a.menu){pause();return;}if(!matchActive||local.dead>0)return;aim=a.aim;const scale=settings.padSensitivity*2.4*(aim?.45:1);local.yaw-=a.lookX*scale*dt;local.pitch=clamp(local.pitch-a.lookY*scale*.75*dt,-1.42,1.42);if(a.reload)reloadGun();if(a.next)switchGun((local.gun+1)%3);if(a.boost)useBoost();
}
function controllerMenu(a,dt){
 const dialog=$('settings').open?$('settings'):$('guide').open?$('guide'):null;
 if(a.back||a.menu){if(dialog)dialog.close();else if(mode==='match'&&paused)resume();else if(mode==='room'&&a.back)lobby();return;}
 const container=dialog||(paused?$('pause-screen'):mode==='room'?$('room-screen'):mode==='result'?$('result-screen'):$('lobby'));
 const elements=[...container.querySelectorAll('button,input,select')].filter(el=>!el.disabled&&el.getClientRects().length);if(!elements.length)return;const buttons=padFrame.sample.buttons;const direction=buttons[12]||a.forward>.55?-1:buttons[13]||a.forward<-.55?1:0;menuRepeat-=dt;
 if(direction&&(menuDirection!==direction||menuRepeat<=0)){let i=elements.indexOf(document.activeElement);elements[(i+direction+elements.length)%elements.length].focus();document.activeElement.scrollIntoView({block:'nearest'});menuRepeat=menuDirection===direction?.18:.4;}menuDirection=direction;
 const focused=elements.includes(document.activeElement)?document.activeElement:elements[0];const left=padFrame.pressed[14],right=padFrame.pressed[15],step=right?1:left?-1:0;
 if(step){if(focused.tagName==='SELECT'){const options=[...focused.options].filter(o=>!o.hidden&&!o.disabled),current=options.indexOf(focused.selectedOptions[0]);focused.value=options[clamp(current+step,0,options.length-1)]?.value||focused.value;focused.dispatchEvent(new Event('change',{bubbles:true}));}else if(focused.type==='range'){focused.value=clamp(+focused.value+step*(+focused.step||1),+focused.min,+focused.max);focused.dispatchEvent(new Event('input',{bubbles:true}));}}
 if(a.accept){if(focused.tagName==='BUTTON')focused.click();else{focused.focus();if(focused.type==='text')toast('Use the keyboard to enter your name or room code.');}}
}

function allPlayers(){if(!online)return [local,rival];const present=new Set(link.members.map(m=>m.side));return [local,...[...remotes.values()].map(r=>r.p)].filter(p=>present.has(p.side));}
function getPlayer(side){return side===local.side?local:remotes.get(side)?.p||(!online&&side===rival.side?rival:null);}
function playerName(side){return side===local.side?ownName():online?(link.members.find(m=>m.side===side)?.name||'Player'):'SENTINEL';}
function makeMatchPlayer(side){const member=link.members.find(m=>m.side===side);if(!online||gameRules.mode!=='tdm')return makePlayer(side);const team=member?.team??0,slot=link.members.filter(m=>m.team===team).findIndex(m=>m.side===side),p=makePlayer(side,Math.max(0,slot)*2+team);p.team=team;return p;}
function buildPlayers(){for(const r of remotes.values())if(r.model!==rivalModel){scene.remove(r.model.root);r.model.root.traverse(o=>{if(o.isMesh){o.geometry.dispose();if(Array.isArray(o.material))o.material.forEach(m=>m.dispose());else o.material.dispose();}});}remotes.clear();local=makeMatchPlayer(online?link.side:0);const members=online?link.members.filter(m=>m.side!==local.side):[{side:1}];members.forEach((m,i)=>{const p=makeMatchPlayer(m.side),model=i===0?rivalModel:makeSoldier([0xff9b70,0xb5a0ff,0xffd179,0x91ccff][m.side%4]);model.setSkin(m.skin||'mint');model.setColor(gameRules.mode==='tdm'?(p.team===0?0x80ffdd:0xffb264):[0xff9b70,0xb5a0ff,0xffd179,0x91ccff][m.side%4]);if(i>0)scene.add(model.root);remotes.set(m.side,{p,model,target:packetPlayer(p)});});rival=[...remotes.values()][0]?.p||makePlayer(1);renderRival=null;rivalName=playerName(rival.side);}
function authorityPlayer(p){return {side:p.side,hp:p.hp,score:p.score,hill:p.hill||0,dead:p.dead,shield:p.shield,...packCombat(p)};}
function applyAuthority(players){if(!Array.isArray(players)||players.length>8)return;for(const data of players){const p=getPlayer(data.side);if(!p||!Number.isFinite(data.hp)||!Number.isFinite(data.score))continue;p.hp=clamp(data.hp,0,100);p.score=clamp(data.score,0,1000);p.hill=clamp(data.hill||0,0,1000);p.dead=Math.max(0,data.dead||0);p.shield=Math.max(0,data.shield||0);receiveCombat(p,data);}}
function nearestPlayer(origin,dir,shooter){let nearest=null;for(const p of allPlayers()){if(p===shooter)continue;const h=hitPlayer(origin,dir,p);if(h&&(!nearest||h.distance<nearest.h.distance))nearest={p,h};}return nearest;}
function renderRoom(){
 if(mode==='room')$('ready').before($('live-rules'));const rules=normalizeRules(link.rules),team=rules.mode==='tdm',mine=link.members.find(m=>m.side===link.side),counts=teamCounts(link.members);
 $('room-kicker').textContent=MODES[rules.mode].toUpperCase()+' · '+(team?counts.join('v')+' / '+rules.capacity/2+'v'+rules.capacity/2+' MAX':link.members.length+'/'+rules.capacity+' PLAYERS MAX');
 $('room-title').textContent=connected?'Squad assembled.':isHost?'Room created.':'Connecting to host…';
 $('room-description').textContent=!mine?'Establishing the player connection. Keep both games open.':'Start with whoever is here. Empty slots and uneven teams are allowed.';
 $('room-roster').replaceChildren(...link.members.map(m=>{const row=document.createElement('div'),name=document.createElement('strong'),state=document.createElement('small');row.className=team?(m.team===0?'cyan-team':'amber-team'):'';name.textContent=(team?TEAM_NAMES[m.team]+' · ':'')+m.name+(m.side===0?' · HOST':'');state.textContent=m.ready?'READY':'CONNECTED';row.append(name,state);return row;}));
 $('team-choice').classList.toggle('hidden',!team||!mine);[0,1].forEach(t=>{const button=$(t===0?'team-cyan':'team-amber');button.textContent=TEAM_NAMES[t]+' · '+counts[t]+'/'+rules.capacity/2+(mine?.team===t?' · YOUR TEAM':'');button.disabled=!mine||link.locked||!canJoinTeam(link.members,link.side,t,rules);button.setAttribute('aria-pressed',String(mine?.team===t));});
 $('live-rules').classList.toggle('hidden',!isHost||link.locked);$('live-mode').value=rules.mode;$('live-map').value=rules.map;
 $('ready').disabled=!mine||ownReady;$('ready').textContent=!mine?'CONNECTING…':ownReady?'READY · WAITING FOR OTHERS':isHost?'START WITH CURRENT PLAYERS ↗':'READY UP ↗';
 $('room-status').textContent=(rules.mode==='hill'?'Hold an uncontested hill for 60 seconds to win.':team?'First team to 30 eliminations. Friendly fire off.':'First to '+rules.limit+' eliminations wins.')+' All present players must be ready. No minimum team size. Join between rounds.';
 if(mode==='result'){$('result-screen').append($('live-rules'));$('rematch-status').textContent=link.members.filter(m=>m.ready).length+'/'+link.members.length+' READY · Everyone chooses Play again.';$('rematch').disabled=ownReady;}
}

function updateScoreList(){const list=allPlayers().slice().sort((a,b)=>points(b,gameRules)-points(a,gameRules));$('match-rule').textContent=gameRules.mode==='hill'?'HILL · FIRST TO 60s':MODES[gameRules.mode].toUpperCase()+' · '+gameRules.limit;$('score-list').classList.toggle('hidden',!online||gameRules.mode==='duel');const key=list.map(p=>p.side+':'+Math.floor(points(p,gameRules))+':'+p.stats.deaths).join('|');if($('score-list').dataset.key!==key){$('score-list').dataset.key=key;$('score-list').replaceChildren(...list.map(p=>{const row=document.createElement('div');row.className=p===local?'me':'';const name=document.createElement('span'),score=document.createElement('b');name.textContent=(gameRules.mode==='tdm'?TEAM_NAMES[p.team]+' · ':'')+playerName(p.side);score.textContent=Math.floor(points(p,gameRules))+(gameRules.mode==='hill'?'s':'');row.append(name,score);return row;}));}const h=gameRules.mode==='hill'?hillState(elapsed,list):null;$('hill-status').textContent=h?(h.contested?'CONTESTED':h.owner===null?'CAPTURE THE HILL':playerName(h.owner)+' CONTROLS')+' · ROTATES IN '+Math.ceil(h.remaining)+'s':'';}
function updateHillVisual(){hillRing.visible=mode==='match'&&gameRules.mode==='hill';if(!hillRing.visible)return;const h=hillState(elapsed,allPlayers());hillRing.position.set(h.center.x,.08,h.center.z);hillRing.material.color.setHex(h.contested?0xffeecc:h.owner===local.side?0x8dffd9:h.owner!==null?0xff986a:0xc7a6ff);hillRing.material.opacity=.65+Math.sin(totalTime*3)*.15;}

function setupPerformanceSettings(){settings.renderPercent=clamp(+settings.renderPercent||100,50,150);for(const [id,key,values]of[['shadow-quality','shadowQuality',['auto','on','off']],['effect-quality','effects',['full','low','off']],['frame-limit','frameLimit',['0','30','60','120','144']]]){if(!values.includes(String(settings[key])))settings[key]=values[0];$(id).value=settings[key];$(id).onchange=()=>{settings[key]=$(id).value;applyQuality();saveSettings();};}$('render-scale').value=settings.renderPercent;$('render-scale-value').textContent=settings.renderPercent+'%';$('render-scale').oninput=()=>{settings.renderPercent=+$('render-scale').value;$('render-scale-value').textContent=settings.renderPercent+'%';applyQuality();saveSettings();};$('team-cyan').onclick=()=>link.chooseTeam(0);$('team-amber').onclick=()=>link.chooseTeam(1);$('room-mode').onchange=()=>{const team=$('room-mode').value==='tdm';for(const option of $('room-capacity').options){const n=+option.value;option.textContent=team?(n/2)+'v'+(n/2)+' maximum':n+' players maximum';}const duel=$('room-mode').value==='duel';$('room-capacity').disabled=duel;if(duel)$('room-capacity').value='2';else if($('room-capacity').value==='2')$('room-capacity').value='4';$('room-capacity').querySelector('[value="2"]').hidden=!duel;};$('room-mode').onchange();applyQuality();}

function updateMatchboard(){const visible=mode==='match'&&!!keys.Tab;$('matchboard').classList.toggle('hidden',!visible);if(!visible)return;const rows=allPlayers().slice().sort((a,b)=>points(b,gameRules)-points(a,gameRules));$('matchboard-rows').replaceChildren(...rows.map(p=>{const row=document.createElement('tr');for(const value of [playerName(p.side),gameRules.mode==='tdm'?TEAM_NAMES[p.team]:'—',p.score,p.stats.deaths,Math.floor(points(p,gameRules)),p===local&&online?link.rtt+' ms':'—']){const cell=document.createElement('td');cell.textContent=value;row.append(cell);}return row;}));}

function syncCloudSettings(){for(const [id,key,mult]of[['sensitivity','sensitivity',1],['fov','fov',1],['volume','volume',100],['music-volume','musicVolume',100],['render-scale','renderPercent',1]]){if($(id)){$(id).value=settings[key]*mult;if($(id+'-value'))$(id+'-value').textContent=settings[key]*mult+(mult===100||id==='render-scale'?'%':'');}}for(const [id,key]of[['quality','quality'],['shadow-quality','shadowQuality'],['effect-quality','effects'],['frame-limit','frameLimit'],['input-mode','inputMode'],['atmosphere','atmosphere'],['reticle-color','reticle'],['camera-motion','motion'],['bot-difficulty','difficulty']])if($(id))$(id).value=settings[key];applyQuality();arena.setAtmosphere(settings.atmosphere);if(audio.master)audio.master.gain.value=settings.volume;if(audio.music)audio.music.gain.value=settings.musicVolume*.16;try{localStorage.setItem('neon-breach-settings-v2',JSON.stringify(settings));}catch{}}
